    function recommendBook(){const unread=books.filter(b=>b.progress<.04);let pool=unread.length?unread:books;if(player.pos.x>37){const contested=pool.filter(b=>b.category==='Contested');if(contested.length)pool=contested}else if(weather==='STORM'){const storm=pool.filter(b=>b.category==='Gothic'||b.category==='Uncanny'||b.category==='Ghosts');if(storm.length)pool=storm}else if(lastReadCategory){const echoes=pool.filter(b=>b.category===lastReadCategory);if(echoes.length)pool=echoes}const quieter=pool.filter(b=>b.fame<90),choice=(quieter.length?quieter:pool)[Math.floor(Math.random()*(quieter.length?quieter.length:pool.length))],reasons={Contested:['It has survived attempts to silence the questions it asks.','Someone, at some point, wanted this book unavailable. It remains available.'],Gothic:['The weather has chosen something with a locked door in it.','This one prefers to be read after the lamps are low.'],Uncanny:['It will make the familiar room feel newly strange.','Nothing in it is impossible, which is exactly the trouble.'],Poetry:['The library thinks you have been listening between sentences.','This one rewards reading slowly, and rereading the same line twice.'],Philosophy:['This one rewards a reader willing to argue in the margins.','It will not tell you what to think, only make you do it.'],Adventure:['You have stood still long enough; this book will travel for you.','It does not stay in one place for very long, and neither will you.'],Society:['Its sharpest mysteries are hidden in ordinary rooms.','It watches a drawing room the way a detective watches a crime scene.'],'Returning Voices':['It was nearly forgotten, and it has things to say about that.','This one has come back into fashion exactly once before, and outlasted the fashion.'],'Almost Unread':['Almost no one has opened this in a very long time. You would be the exception.','Its pages are stiff from disuse, not age. Someone should fix that.'],Archive:['This one exists mostly to be kept, not read. Read it anyway.','It has spent more time being catalogued than being opened.'],Mystery:['It keeps its answer until the last page, and even then, barely.','Something in it does not add up, and that is rather the point.'],Wonder:['It asks you to believe something impossible, briefly, and see what happens.','This one was built to make the ordinary look unfamiliar again.'],'Fading Supernatural':['Whatever haunts this book is losing its grip on being believed.','It is the kind of ghost story that no longer quite frightens anyone, and is sadder for it.'],Memory:['It remembers things more clearly than the people in it do.','This one is less about what happened than about what refuses to be forgotten.'],Speculative:['It wonders what would happen if one thing were different, and follows through.','This one built a whole world out of a single â€œwhat if.â€'],Satire:['It is laughing at something you will recognize immediately.','This one aims its wit at people who never saw it coming.'],Legend:['It has been told and retold long enough to stop needing to be true.','This one predates the idea of an original version.'],Epic:['It takes its time, and asks you to do the same.','This one was built to be read at length, not in passing.'],Drama:['Something in it is about to go wrong for someone, on purpose.','This one was built for a stage, even lying flat on a shelf.'],Sea:['It smells faintly of salt, or you imagine it does.','This one does not stay in sight of land for long.'],History:['It happened, mostly, and the parts that didnâ€™t are the interesting ones.','This one remembers events more honestly than the people who lived them.'],Strange:['Nothing about it behaves quite the way youâ€™d expect.','This one does not explain itself, and is better for it.'],Conscience:['It asks a question you would rather not have to answer.','This one was written by someone arguing with themselves.'],'Fading Speculative':['Its future is now somebodyâ€™s past, and it shows.','This one imagined a tomorrow that quietly stopped arriving.'],Modern:['It is newer than most of what surrounds it on these shelves.','This one hasnâ€™t yet decided what era it belongs to.'],Ghosts:['Something in it has not finished leaving.','This one keeps a door open that most books would close.'],Journey:['It goes somewhere, and takes the long way there on purpose.','This one measures itself in miles, not chapters.'],Customs:['It notices the rules everyone else stopped seeing.','This one is more interested in table manners than in plot.'],Comedy:['It is trying, quite hard, to make you laugh, and it earns it.','This one does not take itself half as seriously as its neighbours do.'],'Fading Adventure':['Its excitement has mellowed into something closer to nostalgia.','This one used to move faster; it has earned the right to slow down.']},genericReasons=['It has been waiting for precisely this kind of visit.','The librarian has her reasons, even for the books she doesnâ€™t explain.','Some recommendations donâ€™t need a reason. This is one of them.'],reasonPool=reasons[choice.category],reason=reasonPool?reasonPool[Math.floor(Math.random()*reasonPool.length)]:genericReasons[Math.floor(Math.random()*genericReasons.length)];showNotice(`The librarian recommends â€œ${choice.title}â€ by ${choice.author}. ${reason}`,8);librarianPause=9;sound(360,.45,'triangle',.1)}
