    const standardInteract=interact;interact=function(){if(focus?.userData?.type!=='memory-door')return standardInteract();const d=focus.userData;if(d.destination==='basement')buildBasement();else if(d.destination==='contested')buildContestedRoom();else if(themeRoomKeys.has(d.destination))buildThemeRooms();else if(d.destination!=='mainhall')buildMemoryRooms();player.pos.set(d.spawn[0],d.spawn[1],d.spawn[2]);player.vel.set(0,0,0);player.yaw=d.yaw;lastSafePosition.copy(player.pos);const arrivals={returning:'The Room of Returning Names receives you in amber light.',quiet:'The Quiet Stacks begin where the polish and conversation end.',unread:'One lamp survives in a room of books almost nobody opens.',repository:'Metal shelving continues beyond the light. Rails tremble beneath the floor.',basement:'The door closes among the pipes of the Below Catalogue.'};showNotice(arrivals[d.destination]||themeArrivals[d.destination]||'The library rearranges itself around you.',6);sound(d.destination==='repository'?58:170,.9,'triangle',.12)};
